static int raydium_i2c_initialize ( struct raydium_data * ts ) { struct i2c_client * client = ts -> client ; int error , retry_cnt ; for ( retry_cnt = 0 ; retry_cnt < RM_MAX_RETRIES ; retry_cnt ++ ) { msleep ( RM_BOOT_DELAY_MS ) ; error = raydium_i2c_check_fw_status ( ts ) ; if ( error ) { dev_err ( & client -> dev , "failed to read 'hello' packet: %d\n" , error ) ; continue ; } if ( ts -> boot_mode == RAYDIUM_TS_BLDR || ts -> boot_mode == RAYDIUM_TS_MAIN ) { break ; } } if ( ts -> boot_mode == RAYDIUM_TS_BLDR ) { raydium_i2c_query_ts_bootloader_info ( ts ) ; } else { raydium_i2c_query_ts_info ( ts ) ; } return error ; } 